{"code": "root = '/repo'
def walk(root):
    out, stack = [], [root]
    while stack:
        d = stack.pop()
        for name in sorted(os.listdir(d)):
            full = d + '/' + name
            if Path(full).is_dir():
                stack.append(full)
            else:
                out.append(full)
    return sorted(out)

for f in walk(root + '/data'):
    rel = f.replace(root+'/','')
    print(rel)"}

